import React, { useState } from "react";
import { messages } from "../../data/messages";
export default function Inbox() { const [selected,setSelected]=useState(messages[0]); return <div><div className="page-heading"><span className="eyebrow">Communication</span><h1>Inbox</h1><p>Messages from teachers and the school office.</p></div><div className="inbox"><div className="message-list">{messages.map(m=><button className={`message-row ${m.unread?"unread":""} ${selected.id===m.id?"selected":""}`} key={m.id} onClick={()=>setSelected(m)}><strong>{m.sender}</strong><span>{m.subject}</span><small>{m.date}</small></button>)}</div><div className="message-view"><span className="eyebrow">{selected.sender}</span><h2>{selected.subject}</h2><small>{selected.date}</small><p>{selected.preview}</p><p>Thank you for staying connected with EduFlow. Please contact the school office if you need any additional information.</p></div></div></div>; }
